The program finds every assignment of the form `name <- expression` in the input and runs them in order. It reads `mod` as Python's `%` operator. Each expression is first checked to contain only numbers, known variable names and arithmetic. It is then evaluated against the current variable values. I did not run it, so I can't quote the final values here.

```python
import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    order = []
    # Find assignments of the form: NAME <- expression ;
    pattern = re.compile(r'\b([A-Za-z_]\w*)\s*<-\s*([^;\n]+)')
    allowed = re.compile(r'^[\w\s+\-*/()%]+$')
    for m in pattern.finditer(text):
        var = m.group(1)
        expr = m.group(2).strip()
        expr_py = re.sub(r'\bmod\b', '%', expr)
        if not allowed.match(expr_py):
            continue
        # Ensure all identifiers are known variables (or numbers)
        ok = True
        for ident in re.findall(r'[A-Za-z_]\w*', expr_py):
            if ident not in env:
                ok = False
                break
        if not ok:
            continue
        try:
            val = eval(expr_py, {"__builtins__": {}}, dict(env))
        except Exception:
            continue
        if var not in env:
            order.append(var)
        env[var] = val

    names = ['a', 'b', 'TMP']
    for v in order:
        if v not in names:
            names.append(v)
    parts = []
    for n in names:
        if n in env:
            parts.append(f"{n} ?= {env[n]};")
    print(" ".join(parts))

if __name__ == "__main__":
    main()
